inline std::string lookup(const EnumEntry* table, size_t count, int64_t value)
{
	for (size_t i = 0; i < count; i++)
	{
		if (table[i].value == value)
		{
			return table[i].name;
		}
	}
	return std::to_string(value);
}

// Decomposes a bitmask into "A | B". Returns "0" when no bits are set, so the
// JSON always carries something a compiler can parse.
inline std::string lookupFlags(const EnumEntry* table, size_t count, int64_t value)
{
	if (value == 0)
	{
		// A zero mask may still have a name of its own (VK_CULL_MODE_NONE).
		for (size_t i = 0; i < count; i++)
		{
			if (table[i].value == 0)
			{
				return table[i].name;
			}
		}
		return "0";
	}

	std::string result;
	int64_t remaining = value;
	for (size_t i = 0; i < count; i++)
	{
		const int64_t bit = table[i].value;
		if (bit != 0 && (remaining & bit) == bit)
		{
			if (!result.empty())
			{
				result += " | ";
			}
			result += table[i].name;
			remaining &= ~bit;
		}
	}
	return result.empty() ? std::to_string(value) : result;
}

#define VKS_ENUM_COUNT(table) (sizeof(table) / sizeof((table)[0]))

inline std::string toString(VkFormat value)
{
	return lookup(kVkFormat, VKS_ENUM_COUNT(kVkFormat), static_cast<int64_t>(value));
}

inline std::string toString(VkAttachmentLoadOp value)
{
	return lookup(kVkAttachmentLoadOp, VKS_ENUM_COUNT(kVkAttachmentLoadOp), static_cast<int64_t>(value));
}

